begin;
select plan(27);
select has_table('public','srk_customer_profiles','customer profile table exists');
select has_table('public','srk_customer_saved_addresses','saved address table exists');
select ok((select relrowsecurity from pg_class where oid='public.srk_customer_profiles'::regclass),'customer profile table has RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.srk_customer_saved_addresses'::regclass),'saved address table has RLS enabled');
select ok(not has_table_privilege('authenticated','public.srk_customer_profiles','SELECT') and not has_table_privilege('authenticated','public.srk_customer_saved_addresses','SELECT'),'customer private tables are not directly readable by authenticated clients');
select has_function('public','srk_customer_get_my_profile',array[]::text[],'customer profile read RPC exists');
select has_function('public','srk_customer_list_my_saved_addresses',array[]::text[],'saved address list RPC exists');
select has_function('public','srk_customer_save_my_address',array['uuid','text','text','text','text','text','text','text','double precision','double precision','boolean'],'saved address upsert RPC exists');
select has_function('public','srk_customer_delete_my_saved_address',array['uuid'],'saved address delete RPC exists');
select ok(has_function_privilege('authenticated','public.srk_customer_get_my_profile()','EXECUTE') and not has_function_privilege('anon','public.srk_customer_get_my_profile()','EXECUTE'),'profile RPC is authenticated-only');
select ok(has_function_privilege('authenticated','public.srk_customer_list_my_saved_addresses()','EXECUTE') and not has_function_privilege('anon','public.srk_customer_list_my_saved_addresses()','EXECUTE'),'saved address list RPC is authenticated-only');
select ok(has_function_privilege('authenticated','public.srk_customer_save_my_address(uuid,text,text,text,text,text,text,text,double precision,double precision,boolean)','EXECUTE') and not has_function_privilege('anon','public.srk_customer_save_my_address(uuid,text,text,text,text,text,text,text,double precision,double precision,boolean)','EXECUTE'),'saved address upsert RPC is authenticated-only');
select ok(has_function_privilege('authenticated','public.srk_customer_delete_my_saved_address(uuid)','EXECUTE') and not has_function_privilege('anon','public.srk_customer_delete_my_saved_address(uuid)','EXECUTE'),'saved address delete RPC is authenticated-only');
select ok(position('auth.uid()' in pg_get_functiondef('public.srk_customer_get_my_profile()'::regprocedure))>0,'profile read is scoped to the authenticated customer');
select ok(position('auth.uid()' in pg_get_functiondef('public.srk_customer_list_my_saved_addresses()'::regprocedure))>0,'saved address list is scoped to the authenticated customer');
select ok(position('auth.uid()' in pg_get_functiondef('public.srk_customer_save_my_address(uuid,text,text,text,text,text,text,text,double precision,double precision,boolean)'::regprocedure))>0,'saved address writes use the authenticated customer identity');
select ok(position('auth.uid()' in pg_get_functiondef('public.srk_customer_delete_my_saved_address(uuid)'::regprocedure))>0,'saved address deletion uses the authenticated customer identity');
select ok(position('ADDRESS_LIMIT_REACHED' in pg_get_functiondef('public.srk_customer_save_my_address(uuid,text,text,text,text,text,text,text,double precision,double precision,boolean)'::regprocedure))>0,'saved address count is capped at ten');
select ok(position('pg_advisory_xact_lock' in pg_get_functiondef('public.srk_customer_save_my_address(uuid,text,text,text,text,text,text,text,double precision,double precision,boolean)'::regprocedure))>0,'concurrent address creation is serialized per customer');
select ok(exists(select 1 from pg_indexes where schemaname='public' and indexname='srk_customer_saved_addresses_one_default_uidx'),'only one default address is allowed per customer');
select ok(exists(select 1 from storage.buckets where id='srk-customer-avatars' and public=false and file_size_limit=5242880 and allowed_mime_types @> array['image/jpeg','image/png','image/webp']),'avatar bucket is private with restricted MIME types and 5 MB limit');
select ok(exists(select 1 from storage.buckets where id='srk-customer-support' and public=false and file_size_limit=10485760 and allowed_mime_types @> array['image/jpeg','image/png','image/webp','application/pdf']),'support bucket is private with restricted MIME types and 10 MB limit');
select ok(exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='srk_customer_avatar_upload_own' and cmd='INSERT'),'avatar upload policy is present');
select ok(exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='srk_customer_support_upload_own' and cmd='INSERT'),'support upload policy is present and complaint-scoped');
select ok(not exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='srk_customer_support_delete_own') and exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='srk_customer_support_delete_unlinked_own'),'customers can clean up unlinked uploads but cannot delete linked support evidence');
select ok(exists(select 1 from pg_policies where schemaname='storage' and tablename='objects' and policyname='srk_customer_avatar_delete_own' and position('srk_customer_profiles' in coalesce(qual,''))>0),'a customer cannot delete an avatar still referenced by their profile');
select ok(has_function_privilege('authenticated','public.srk_customer_update_my_profile(text,text,text)','EXECUTE') and not has_function_privilege('anon','public.srk_customer_update_my_profile(text,text,text)','EXECUTE'),'avatar profile update RPC is authenticated-only');
select * from finish();
rollback;
